import { defineConfig, loadEnv } from 'vite'
import react from '@vitejs/plugin-react'
import { readFileSync } from 'node:fs'

// Read the run-id from the artifacts directory so we can isolate
// the counter state for each run/session.
let runId = ''
try {
  runId = readFileSync('/logs/artifacts/run-id', 'utf-8').trim()
} catch (err) {
  console.warn('Could not read /logs/artifacts/run-id:', err)
}

// https://vite.dev/config/
export default defineConfig(({ mode }) => {
  // Load existing env variables for this mode (e.g. .env, .env.development).
  const env = loadEnv(mode, process.cwd(), '')

  // Inject the run-id from /logs/artifacts/run-id into the Vite env.
  // This will be exposed to the client as import.meta.env.VITE_RUN_ID.
  env.VITE_RUN_ID = runId

  // Ensure VITE_CONVEX_URL is set from the process environment if available.
  if (!env.VITE_CONVEX_URL && process.env.VITE_CONVEX_URL) {
    env.VITE_CONVEX_URL = process.env.VITE_CONVEX_URL
  }

  return {
    plugins: [react()],
    server: {
      host: true,
      port: 5173,
      strictPort: true,
    },
    preview: {
      host: true,
      port: 5173,
      strictPort: true,
    },
    define: {
      'import.meta.env.VITE_RUN_ID': JSON.stringify(runId),
    },
  }
})

import { useQuery, useMutation } from 'convex/react'
import { api } from '../convex/_generated/api'
import './App.css'

// The run-id is injected at build/dev time from /logs/artifacts/run-id.
// This isolates the counter state for each run/session.
const RUN_ID = import.meta.env.VITE_RUN_ID as string

function App() {
  // Reactive query that re-runs whenever the counter changes.
  const count = useQuery(api.counter.getCount, { runId: RUN_ID }) ?? 0
  const increment = useMutation(api.counter.increment)

  const handleIncrement = () => {
    void increment({ runId: RUN_ID })
  }

  return (
    <div className="app">
      <header>
        <h1>Collaborative Counter</h1>
        <p className="subtitle">
          Powered by React + Convex. Open this page in another tab and try it!
        </p>
      </header>
      <main className="counter-card">
        <div className="count-display" data-testid="count">
          {count}
        </div>
        <button
          type="button"
          className="increment-button"
          onClick={handleIncrement}
        >
          Increment
        </button>
        <p className="run-id">Run ID: {RUN_ID}</p>
      </main>
    </div>
  )
}

export default App

